**解决方案**：
```javascript
// 缓存DOM引用
class UIManager {
    constructor() {
        this.elements = {
            columns: new Map(),
            panels: new Map()
        };
        this.cacheElements();
    }

    cacheElements() {
        ['workspace', 'list', 'mindmap', 'detail'].forEach(view => {
            this.elements.columns.set(view, document.getElementById(`${view}-column`));
        });
    }
}
```

