class ModernUIController {
    constructor(container) {
        this.mindmapService = container.get('mindmapService');
        this.registryService = container.get('registryService');
        this.eventBus = container.get('eventBus');

        this.columnManager = new ColumnManager(this.eventBus);
        this.setupEventHandlers();
    }
}
```

### **Phase 2: 事件系统集成 (1天)**
```javascript
// 替换全局事件为事件总线
class UIEventBridge {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.migrateGlobalEvents();
    }

    migrateGlobalEvents() {
        // 将window事件迁移到eventBus
        this.eventBus.on('mindmap:rendered', this.handleMindmapRendered.bind(this));
        this.eventBus.on('mindmap:removed', this.handleMindmapRemoved.bind(this));
    }
}
```

### **Phase 3: 状态管理集成 (1天)**
```javascript
// UI状态管理器
class UIStateManager {
    constructor(stateManager) {
        this.stateManager = stateManager;
        this.initUIState();
    }

    initUIState() {
        this.stateManager.setState('ui.activeViews', ['list', 'mindmap', 'detail']);
        this.stateManager.setState('ui.currentProject', null);
    }

    updateActiveViews(views) {
        this.stateManager.setState('ui.activeViews', views);
    }
}
```

## 🎉 **适配结论**

### **✅ UI部分完全可以无大改造适配新架构**

