class LegacyBridge {
    constructor(nextApp) {
        this.nextApp = nextApp;
        this.syncInterval = null;
    }

    // 启动双向同步
    startSync() {
        // 监听旧系统变化
        this.watchLegacyChanges();

        // 监听新系统变化
        this.nextApp.eventBus.on('data:changed', (event) => {
            this.syncToLegacy(event.data);
        });

        // 定期同步
        this.syncInterval = setInterval(() => {
            this.performSync();
        }, 5000);
    }

    // 从旧系统迁移数据
    async migrateFromLegacy() {
        const legacyData = this.extractLegacyData();
        const migratedData = this.transformData(legacyData);
        await this.nextApp.dataManager.importData(migratedData);
    }
}
```

### 4.2 渐进式切换机制
```javascript
class ProgressiveSwitcher {
    constructor() {
        this.features = new Map();
        this.switchRatio = 0; // 0-100，控制切换比例
    }

    // 注册功能切换
    registerFeature(name, legacyImpl, nextImpl) {
        this.features.set(name, { legacy: legacyImpl, next: nextImpl });
    }

    // 根据切换比例选择实现
    getImplementation(featureName) {
        const feature = this.features.get(featureName);
        const useNext = Math.random() * 100 < this.switchRatio;
        return useNext ? feature.next : feature.legacy;
    }

    // 逐步提高新系统使用率
    increaseSwitchRatio(increment = 10) {
        this.switchRatio = Math.min(100, this.switchRatio + increment);
    }
}
```

## 🎯 Phase 5: 平滑切换 (1-2天)

### 5.1 切换策略
