// 新增: 数据一致性验证器
class DataConsistencyValidator {
    constructor() {
        this.validationRules = [];
        this.repairStrategies = new Map();
    }

    // 验证节点内容一致性
    validateNodeContentConsistency(node) {
        // 检查node.content和node.data.content一致性
        const contentValid = node.content === node.data?.content;
        if (!contentValid) {
            return this.repairNodeContent(node);
        }
        return node;
    }

    // 验证整体数据结构
    validateMindmapStructure(mindmap) {
        // 检查ID唯一性、父子关系正确性等
        const idMap = new Map();
        let hasErrors = false;

        this.traverseNodes(mindmap, node => {
            if (idMap.has(node.id)) hasErrors = true;
            idMap.set(node.id, node);
        });

        return !hasErrors;
    }
}
