### 2. 拖拽管理器实现 (2天)

```javascript
// 原生拖拽实现
class DragDropManager {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.draggedNode = null;
        this.draggedElement = null;
        this.dropTarget = null;
        this.dragStartPos = { x: 0, y: 0 };
        this.placeholderElement = null;

        // 拖拽状态
        this.state = {
            isDragging: false,
            isValidTarget: false,
            dropPosition: null, // 'before', 'after', 'child'
        };
    }

    // 初始化拖拽
    initialize() {
        this.setupDragEvents();
    }

    // 设置拖拽事件
    setupDragEvents() {
        // 使用原生HTML5拖拽API
        document.addEventListener('mousedown', this.handleMouseDown.bind(this));
        document.addEventListener('mousemove', this.handleMouseMove.bind(this));
        document.addEventListener('mouseup', this.handleMouseUp.bind(this));

        // 触摸设备支持
        document.addEventListener('touchstart', this.handleTouchStart.bind(this));
        document.addEventListener('touchmove', this.handleTouchMove.bind(this));
        document.addEventListener('touchend', this.handleTouchEnd.bind(this));
    }

    // 处理拖拽开始
    handleDragStart(nodeElement, event) {
        const nodeId = nodeElement.dataset.nodeId;
        const node = this.mindmap.nodes.get(nodeId);

        // 不允许拖拽根节点
        if (node.isRoot) return;

        this.state.isDragging = true;
        this.draggedNode = node;
        this.draggedElement = nodeElement;
        this.dragStartPos = { 
            x: event.clientX || event.touches[0].clientX,
            y: event.clientY || event.touches[0].clientY
        };

        // 创建拖拽占位元素
        this.createPlaceholder(nodeElement);

        // 通知事件系统
        this.mindmap.eventBus.emit('node:dragstart', { node });
    }

    // 处理拖拽移动
    handleDragMove(event) {
        if (!this.state.isDragging) return;

        const currentPos = {
            x: event.clientX || event.touches[0].clientX,
            y: event.clientY || event.touches[0].clientY
        };

        // 更新拖拽元素位置
        this.updateDragElementPosition(currentPos);

        // 查找潜在放置目标
        const targetElement = this.findDropTarget(currentPos);
        if (targetElement) {
            const targetNodeId = targetElement.dataset.nodeId;
            const targetNode = this.mindmap.nodes.get(targetNodeId);

            // 检查拖放规则
            if (this.validateDropTarget(this.draggedNode, targetNode)) {
                this.dropTarget = targetNode;
                this.state.isValidTarget = true;

                // 计算放置位置（前、后、成为子节点）
                this.calculateDropPosition(targetElement, currentPos);

                // 显示放置指示器
                this.showDropIndicator(targetElement);
            } else {
                this.clearDropTarget();
            }
        } else {
            this.clearDropTarget();
        }
    }

    // 处理拖拽结束
    handleDragEnd() {
        if (!this.state.isDragging) return;

        // 如果有有效的放置目标
        if (this.state.isValidTarget && this.dropTarget) {
            // 执行节点移动
            this.executeNodeMove(
                this.draggedNode, 
                this.dropTarget, 
                this.state.dropPosition
            );

            // 通知事件系统
            this.mindmap.eventBus.emit('node:moved', {
                node: this.draggedNode,
                target: this.dropTarget,
                position: this.state.dropPosition
            });
        }

        // 清理
        this.removePlaceholder();
        this.removeDropIndicator();

        // 重置状态
        this.state.isDragging = false;
        this.state.isValidTarget = false;
        this.draggedNode = null;
        this.draggedElement = null;
        this.dropTarget = null;

        // 重新布局和渲染
        this.mindmap.layoutEngine.layout();
        this.mindmap.renderEngine.render();
    }

    // 验证放置目标
    validateDropTarget(draggedNode, targetNode) {
        // 规则1: 不能将节点移动到其自身或其子孙节点下
        if (this.isDescendantOf(targetNode, draggedNode)) {
            return false;
        }

        // 规则2: 不能将节点移动到同一个位置
        if (targetNode.parent === draggedNode.parent && 
            this.getNodeIndex(targetNode) === this.getNodeIndex(draggedNode)) {
            return false;
        }

        return true;
    }

    // 执行节点移动
    executeNodeMove(node, target, position) {
        // 保存移动前的状态
        const oldParent = node.parent;
        const oldIndex = this.getNodeIndex(node);

        // 根据放置位置决定移动策略
        switch(position) {
            case 'before':
                this.mindmap.moveNodeBefore(node.id, target.id);
                break;

            case 'after':
                this.mindmap.moveNodeAfter(node.id, target.id);
                break;

            case 'child':
                this.mindmap.moveNodeToChild(node.id, target.id);
                break;
        }

        // 存储操作以支持撤销
        this.mindmap.history.push({
            type: 'move',
            node: node.id,
            oldParent: oldParent.id,
            oldIndex,
            newParent: node.parent.id,
            newIndex: this.getNodeIndex(node)
        });
    }
}
```

### 3. 布局引擎与渲染系统 (2天)

```javascript
// 布局引擎
class LayoutEngine {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.layoutAlgorithm = 'horizontal-tree'; // 默认布局算法
        this.nodeSpacing = 60;  // 节点间距
        this.levelSpacing = 80; // 层级间距
    }

    // 计算布局
    layout() {
        switch (this.layoutAlgorithm) {
            case 'horizontal-tree':
                this.horizontalTreeLayout();
                break;

            case 'vertical-tree':
                this.verticalTreeLayout();
                break;

            case 'mind-map':
                this.mindMapLayout();
                break;

            default:
                this.horizontalTreeLayout();
        }
    }

    // 水平树布局
    horizontalTreeLayout() {
        // 递归布局算法
        const layoutNode = (node, x, y, level) => {
            // 设置节点位置
            node.x = x;
            node.y = y;

            // 计算子节点布局
            if (node.children && node.children.length) {
                const childY = y - ((node.children.length - 1) * this.nodeSpacing) / 2;

                node.children.forEach((child, index) => {
                    const childX = x + this.levelSpacing;
                    const yOffset = childY + index * this.nodeSpacing;

                    layoutNode(child, childX, yOffset, level + 1);
                });
            }
        };

        // 从根节点开始布局
        layoutNode(this.mindmap.root, 0, 0, 0);
    }
}

// 渲染引擎
class RenderEngine {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.canvas = null;
        this.ctx = null;
        this.nodeElements = new Map();
        this.connectionElements = new Map();
        this.containerElement = null;
        this.svgElement = null;
    }

    // 初始化渲染引擎
    initialize() {
        this.containerElement = this.mindmap.container;
        this.containerElement.classList.add('mindmap-container');

        // 创建SVG元素用于连线绘制
        this.svgElement = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        this.svgElement.classList.add('mindmap-connections');
        this.containerElement.appendChild(this.svgElement);

        // 创建节点容器
        this.nodeContainer = document.createElement('div');
        this.nodeContainer.classList.add('mindmap-nodes');
        this.containerElement.appendChild(this.nodeContainer);
    }

    // 渲染脑图
    render() {
        // 清除现有节点
        this.nodeContainer.innerHTML = '';
        this.svgElement.innerHTML = '';
        this.nodeElements.clear();
        this.connectionElements.clear();

        // 渲染节点和连线
        this.renderNode(this.mindmap.root);
        this.renderConnections();

        // 居中显示
        this.centerView();
    }

    // 渲染单个节点
    renderNode(node) {
        const nodeElement = document.createElement('div');
        nodeElement.className = 'mindmap-node';
        nodeElement.dataset.nodeId = node.id;

        if (node.isRoot) nodeElement.classList.add('root-node');
        if (node === this.mindmap.selected) nodeElement.classList.add('selected');

        // 设置位置
        nodeElement.style.left = `${node.x}px`;
        nodeElement.style.top = `${node.y}px`;

        // 设置内容
        nodeElement.innerHTML = `
            <div class="node-content">
                <div class="node-title">${node.title || 'Untitled'}</div>
                ${node.content ? `<div class="node-description">${node.content}</div>` : ''}
            </div>
            ${this.mindmap.options.editable ? `
                <div class="node-buttons">
                    <button class="add-btn">+</button>
                    <button class="edit-btn">✎</button>
                    <button class="delete-btn">×</button>
                </div>
            ` : ''}
        `;

        // 添加到容器
        this.nodeContainer.appendChild(nodeElement);
        this.nodeElements.set(node.id, nodeElement);

        // 递归渲染子节点
        if (node.children) {
            node.children.forEach(child => this.renderNode(child));
        }
    }

    // 渲染连接线
    renderConnections() {
        const renderConnection = (parent, child) => {
            const parentEl = this.nodeElements.get(parent.id);
            const childEl = this.nodeElements.get(child.id);

            if (!parentEl || !childEl) return;

            // 计算连接点
            const parentRect = parentEl.getBoundingClientRect();
            const childRect = childEl.getBoundingClientRect();
            const containerRect = this.containerElement.getBoundingClientRect();

            const parentX = parentRect.x + parentRect.width - containerRect.x;
            const parentY = parentRect.y + parentRect.height/2 - containerRect.y;
            const childX = childRect.x - containerRect.x;
            const childY = childRect.y + childRect.height/2 - containerRect.y;

            // 创建连接线路径
            const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');

            // 计算贝塞尔曲线控制点
            const controlX1 = parentX + 50;
            const controlX2 = childX - 50;

            path.setAttribute('d', `M ${parentX} ${parentY} C ${controlX1} ${parentY}, ${controlX2} ${childY}, ${childX} ${childY}`);
            path.setAttribute('stroke', '#888');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('fill', 'none');

            this.svgElement.appendChild(path);
            this.connectionElements.set(`${parent.id}-${child.id}`, path);
        };

        // 递归处理所有连接
        const processNode = (node) => {
            if (node.children) {
                node.children.forEach(child => {
                    renderConnection(node, child);
                    processNode(child);
                });
            }
        };

        processNode(this.mindmap.root);
    }
}
