    handleClick(event) {
        // 如果正在编辑，先保存
        if (this.state.isEditing) {
            this.finishEditing();
        }

        // 查找点击的节点
        const nodeElement = event.target.closest('.mindmap-node');
        if (nodeElement) {
            const nodeId = nodeElement.dataset.nodeId;
            const node = this.mindmap.nodes.get(nodeId);

            // 处理节点选择
            if (node) {
                this.mindmap.selectNode(nodeId);
            }

            // 处理按钮点击
            if (event.target.classList.contains('add-btn')) {
                this.addChildNode(node);
            } else if (event.target.classList.contains('edit-btn')) {
                this.startEditing(node, nodeElement);
            } else if (event.target.classList.contains('delete-btn')) {
                this.confirmDeleteNode(node);
            }
        } else {
            // 点击空白区域，取消选择
            this.mindmap.selectNode(null);
        }
    }

    // 开始编辑节点
    startEditing(node, nodeElement) {
        // 标记编辑状态
        this.state.isEditing = true;
        this.state.editingNode = node;

        // 获取节点内容元素
        const contentEl = nodeElement.querySelector('.node-content');
        const titleEl = contentEl.querySelector('.node-title');

        // 创建编辑器
        const editor = document.createElement('div');
        editor.className = 'node-editor';
        editor.innerHTML = `
            <input type="text" class="title-input" value="${node.title || ''}" placeholder="Title">
            <textarea class="content-input" placeholder="Content">${node.content || ''}</textarea>
            <div class="editor-buttons">
                <button class="save-btn">Save</button>
                <button class="cancel-btn">Cancel</button>
            </div>
        `;

        // 替换内容
        contentEl.innerHTML = '';
        contentEl.appendChild(editor);

        // 聚焦标题输入
        const titleInput = editor.querySelector('.title-input');
        titleInput.focus();
        titleInput.select();

        // 绑定按钮事件
        editor.querySelector('.save-btn').addEventListener('click', () => this.saveEditing());
        editor.querySelector('.cancel-btn').addEventListener('click', () => this.cancelEditing());

        // ESC和Enter键处理
        editor.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                this.cancelEditing();
            } else if (e.key === 'Enter' && e.ctrlKey) {
                this.saveEditing();
            }
        });

        // 通知事件
        this.eventBus.emit('node:editing', { node });
    }

    // 保存编辑
    saveEditing() {
        if (!this.state.isEditing) return;

        const node = this.state.editingNode;
        const nodeElement = this.mindmap.renderEngine.nodeElements.get(node.id);
        const editor = nodeElement.querySelector('.node-editor');

        // 获取编辑的值
        const title = editor.querySelector('.title-input').value.trim();
        const content = editor.querySelector('.content-input').value.trim();

        // 更新节点数据
        const updates = {};
        if (title !== node.title) updates.title = title;
        if (content !== node.content) updates.content = content;

        if (Object.keys(updates).length > 0) {
            this.mindmap.updateNode(node.id, updates);

            // 通知事件
            this.eventBus.emit('node:updated', { node, updates });
        }

        // 重置编辑状态
        this.finishEditing();

        // 重新渲染节点
        this.mindmap.renderEngine.renderNode(node);
    }
}
