// 数据管理器
class DataManager {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.eventBus = mindmap.eventBus;
        this.storageAdapter = null; // 存储适配器
    }

    // 设置存储适配器
    setStorageAdapter(adapter) {
        this.storageAdapter = adapter;
    }

    // 保存当前脑图
    async save(id, options = {}) {
        if (!this.storageAdapter) {
            console.warn('No storage adapter set, unable to save mindmap');
            return { success: false, error: 'No storage adapter' };
        }

        try {
            // 准备数据
            const data = this.prepareForSave();

            // 元数据
            const metadata = {
                id: id || this.mindmap.id,
                createdAt: this.mindmap.createdAt || new Date().toISOString(),
                updatedAt: new Date().toISOString(),
                version: '1.0',
                nodeCount: this.countNodes(),
                ...options.metadata
            };

            // 包装数据
            const mindPack = {
                format: 'mindpack_v1',
                data,
                metadata
            };

            // 存储
            const result = await this.storageAdapter.save(metadata.id, mindPack);

            // 更新脑图ID
            if (result.success && !this.mindmap.id) {
                this.mindmap.id = metadata.id;
            }

            // 通知事件
            this.eventBus.emit('mindmap:saved', {
                id: metadata.id,
                metadata,
                result
            });

            return result;
        } catch (error) {
            console.error('Failed to save mindmap:', error);
            return { success: false, error: error.message };
        }
    }

    // 加载脑图
    async load(id, options = {}) {
        if (!this.storageAdapter) {
            console.warn('No storage adapter set, unable to load mindmap');
            return { success: false, error: 'No storage adapter' };
        }

        try {
            // 加载数据
            const result = await this.storageAdapter.load(id);

            if (!result.success) {
                return result;
            }

            const { data: mindPack } = result;

            // 验证数据格式
            if (!mindPack || !mindPack.format || !mindPack.data) {
                return { success: false, error: 'Invalid mindmap data format' };
            }

            // 设置脑图数据
            this.mindmap.setData(mindPack.data);
            this.mindmap.id = id;

            if (mindPack.metadata) {
                this.mindmap.createdAt = mindPack.metadata.createdAt;
                this.mindmap.updatedAt = mindPack.metadata.updatedAt;
            }

            // 通知事件
            this.eventBus.emit('mindmap:loaded', {
                id,
                metadata: mindPack.metadata
            });

            // 重新布局和渲染
            this.mindmap.layoutEngine.layout();
            this.mindmap.renderEngine.render();

            return { success: true };
        } catch (error) {
            console.error('Failed to load mindmap:', error);
            return { success: false, error: error.message };
        }
    }

    // 准备保存数据
    prepareForSave() {
        // 转换为纯数据结构
        const serializeNode = (node) => {
            const serialized = {
                id: node.id,
                title: node.title,
                content: node.content
            };

            if (node.data) {
                serialized.data = { ...node.data };
            }

            if (node.children && node.children.length > 0) {
                serialized.children = node.children.map(child => serializeNode(child));
            }

            return serialized;
        };

        return serializeNode(this.mindmap.root);
    }
}
