### 3. 脑图核心模块实现 (3-4天)

```javascript
// 脑图核心
class MindmapCore {
    constructor(options = {}) {
        this.options = {
            container: null,      // DOM容器
            theme: 'default',     // 主题
            editable: true,       // 是否可编辑
            draggable: true,      // 是否可拖拽
            ...options
        };

        this.nodes = new Map();   // 节点映射
        this.root = null;         // 根节点
        this.selected = null;     // 当前选中节点
        this.eventBus = null;     // 事件总线

        this.dragManager = new DragDropManager(this);
        this.layoutEngine = new LayoutEngine(this);
        this.renderEngine = new RenderEngine(this);
    }

    // 初始化
    initialize(container, data) {
        this.container = container;
        this.setData(data);
        this.renderEngine.initialize();
        this.dragManager.initialize();
        this.layoutEngine.layout();
        this.renderEngine.render();
    }

    // 设置数据
    setData(data) {
        this.root = this.buildNodeTree(data);
        this.selected = null;
    }

    // 构建节点树
    buildNodeTree(nodeData, parent = null) {
        const node = {
            id: nodeData.id || `node_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
            title: nodeData.title || nodeData.topic || '',
            content: nodeData.content || '',
            data: nodeData.data || {},
            parent: parent,
            isRoot: !parent,
            children: [],
            x: 0,
            y: 0,
            expanded: true
        };

        // 注册节点
        this.nodes.set(node.id, node);

        // 处理子节点
        if (nodeData.children && Array.isArray(nodeData.children)) {
            node.children = nodeData.children.map(childData => 
                this.buildNodeTree(childData, node)
            );
        }

        return node;
    }

    // 添加节点
    addNode(parentId, nodeData) {
        const parent = this.nodes.get(parentId);
        if (!parent) return null;

        const newNode = this.buildNodeTree({
            ...nodeData,
            id: nodeData.id || `node_${Date.now()}_${Math.floor(Math.random() * 10000)}`
        }, parent);

        parent.children.push(newNode);

        // 重新布局和渲染
        this.layoutEngine.layout();
        this.renderEngine.render();

        // 通知事件
        if (this.eventBus) {
            this.eventBus.emit('node:added', {
                node: newNode,
                parent
            });
        }

        return newNode;
    }

    // 移动节点
    moveNode(nodeId, newParentId, index = -1) {
        const node = this.nodes.get(nodeId);
        const newParent = this.nodes.get(newParentId);

        if (!node || !newParent || node === newParent) return false;
        if (node.isRoot) return false; // 不允许移动根节点

        // 检查是否移动到子孙节点
        if (this.isDescendantOf(newParent, node)) return false;

        // 保存原始父节点
        const oldParent = node.parent;

        // 从原父节点中移除
        if (oldParent) {
            oldParent.children = oldParent.children.filter(child => child !== node);
        }

        // 添加到新父节点
        node.parent = newParent;

        if (index >= 0 && index < newParent.children.length) {
            // 插入到特定位置
            newParent.children.splice(index, 0, node);
        } else {
            // 添加到末尾
            newParent.children.push(node);
        }

        // 重新布局和渲染
        this.layoutEngine.layout();
        this.renderEngine.render();

        // 通知事件
        if (this.eventBus) {
            this.eventBus.emit('node:moved', {
                node,
                oldParent,
                newParent
            });
        }

        return true;
    }

    // 判断是否是子孙节点
    isDescendantOf(node, potentialAncestor) {
        let current = node;
        while (current) {
            if (current === potentialAncestor) return true;
            current = current.parent;
        }
        return false;
    }
}
