// 拖拽管理器 - 使用原生拖拽API
class DragDropManager {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.draggedNode = null;
        this.draggedElement = null;
        this.dropTarget = null;
        this.dragStartPos = { x: 0, y: 0 };
        this.placeholderElement = null;

        // 拖拽状态
        this.state = {
            isDragging: false,
            isValidTarget: false,
            dropPosition: null, // 'before', 'after', 'child'
        };
    }

    // 初始化拖拽
    initialize() {
        this.setupDragEvents();
    }

    // 设置拖拽事件
    setupDragEvents() {
        document.addEventListener('mousedown', this.handleMouseDown.bind(this));
        document.addEventListener('mousemove', this.handleMouseMove.bind(this));
        document.addEventListener('mouseup', this.handleMouseUp.bind(this));

        // 触摸设备支持
        document.addEventListener('touchstart', this.handleTouchStart.bind(this));
        document.addEventListener('touchmove', this.handleTouchMove.bind(this));
        document.addEventListener('touchend', this.handleTouchEnd.bind(this));
    }

    // 处理鼠标按下
    handleMouseDown(e) {
        const nodeElement = e.target.closest('.mindmap-node');
        if (!nodeElement) return;

        // 不处理编辑按钮点击
        if (e.target.closest('.node-buttons')) return;

        const nodeId = nodeElement.dataset.nodeId;
        const node = this.mindmap.nodes.get(nodeId);

        // 不拖拽根节点
        if (node && !node.isRoot) {
            // 阻止默认行为和文本选择
            e.preventDefault();

            // 延迟启动拖拽，避免点击误操作
            this.dragTimeout = setTimeout(() => {
                this.handleDragStart(nodeElement, e);
            }, 200);
        }
    }

    // 处理鼠标移动
    handleMouseMove(e) {
        if (this.dragTimeout) {
            clearTimeout(this.dragTimeout);
            this.dragTimeout = null;
        }

        if (this.state.isDragging) {
            e.preventDefault();
            this.handleDragMove(e);
        }
    }

    // 处理鼠标释放
    handleMouseUp(e) {
        if (this.dragTimeout) {
            clearTimeout(this.dragTimeout);
            this.dragTimeout = null;
        }

        if (this.state.isDragging) {
            e.preventDefault();
            this.handleDragEnd();
        }
    }

    // 创建拖拽占位元素
    createPlaceholder(nodeElement) {
        const rect = nodeElement.getBoundingClientRect();

        this.placeholderElement = document.createElement('div');
        this.placeholderElement.className = 'mindmap-drag-placeholder';
        this.placeholderElement.style.width = `${rect.width}px`;
        this.placeholderElement.style.height = `${rect.height}px`;

        // 克隆内容
        this.placeholderElement.innerHTML = nodeElement.innerHTML;

        // 添加到body
        document.body.appendChild(this.placeholderElement);

        // 设置初始位置
        this.placeholderElement.style.position = 'absolute';
        this.placeholderElement.style.left = `${rect.left}px`;
        this.placeholderElement.style.top = `${rect.top}px`;
        this.placeholderElement.style.zIndex = '9999';

        // 应用拖拽样式
        nodeElement.classList.add('dragging');
    }

    // 更新拖拽元素位置
    updateDragElementPosition(pos) {
        if (!this.placeholderElement) return;

        const deltaX = pos.x - this.dragStartPos.x;
        const deltaY = pos.y - this.dragStartPos.y;

        const rect = this.draggedElement.getBoundingClientRect();

        this.placeholderElement.style.left = `${rect.left + deltaX}px`;
        this.placeholderElement.style.top = `${rect.top + deltaY}px`;
    }

    // 执行拖拽结束动作
    executeNodeMove() {
        if (!this.state.isValidTarget || !this.dropTarget) return false;

        const node = this.draggedNode;
        const target = this.dropTarget;

        switch (this.state.dropPosition) {
            case 'before':
                // 获取目标节点在父节点中的索引
                const beforeIndex = target.parent.children.indexOf(target);
                return this.mindmap.moveNode(node.id, target.parent.id, beforeIndex);

            case 'after':
                // 获取目标节点在父节点中的索引
                const afterIndex = target.parent.children.indexOf(target) + 1;
                return this.mindmap.moveNode(node.id, target.parent.id, afterIndex);

            case 'child':
                // 添加为子节点
                return this.mindmap.moveNode(node.id, target.id);

            default:
                return false;
        }
    }
}
