### 3. 布局引擎与渲染系统 (2天)

```javascript
// 布局引擎
class LayoutEngine {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.layoutAlgorithm = 'horizontal-tree'; // 默认布局算法
        this.nodeSpacing = 60;  // 节点间距
        this.levelSpacing = 80; // 层级间距
    }

    // 计算布局
    layout() {
        switch (this.layoutAlgorithm) {
            case 'horizontal-tree':
                this.horizontalTreeLayout();
                break;

            case 'vertical-tree':
                this.verticalTreeLayout();
                break;

            case 'mind-map':
                this.mindMapLayout();
                break;

            default:
                this.horizontalTreeLayout();
        }
    }

    // 水平树布局
    horizontalTreeLayout() {
        // 递归布局算法
        const layoutNode = (node, x, y, level) => {
            // 设置节点位置
            node.x = x;
            node.y = y;

            // 计算子节点布局
            if (node.children && node.children.length) {
                const childY = y - ((node.children.length - 1) * this.nodeSpacing) / 2;

                node.children.forEach((child, index) => {
                    const childX = x + this.levelSpacing;
                    const yOffset = childY + index * this.nodeSpacing;

                    layoutNode(child, childX, yOffset, level + 1);
                });
            }
        };

        // 从根节点开始布局
        layoutNode(this.mindmap.root, 0, 0, 0);
    }
}

// 渲染引擎
class RenderEngine {
    constructor(mindmap) {
        this.mindmap = mindmap;
        this.canvas = null;
        this.ctx = null;
        this.nodeElements = new Map();
        this.connectionElements = new Map();
        this.containerElement = null;
        this.svgElement = null;
    }

    // 初始化渲染引擎
    initialize() {
        this.containerElement = this.mindmap.container;
        this.containerElement.classList.add('mindmap-container');

        // 创建SVG元素用于连线绘制
        this.svgElement = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        this.svgElement.classList.add('mindmap-connections');
        this.containerElement.appendChild(this.svgElement);

        // 创建节点容器
        this.nodeContainer = document.createElement('div');
        this.nodeContainer.classList.add('mindmap-nodes');
        this.containerElement.appendChild(this.nodeContainer);
    }

    // 渲染脑图
    render() {
        // 清除现有节点
        this.nodeContainer.innerHTML = '';
        this.svgElement.innerHTML = '';
        this.nodeElements.clear();
        this.connectionElements.clear();

        // 渲染节点和连线
        this.renderNode(this.mindmap.root);
        this.renderConnections();

        // 居中显示
        this.centerView();
    }

    // 渲染单个节点
    renderNode(node) {
        const nodeElement = document.createElement('div');
        nodeElement.className = 'mindmap-node';
        nodeElement.dataset.nodeId = node.id;

        if (node.isRoot) nodeElement.classList.add('root-node');
        if (node === this.mindmap.selected) nodeElement.classList.add('selected');

        // 设置位置
        nodeElement.style.left = `${node.x}px`;
        nodeElement.style.top = `${node.y}px`;

        // 设置内容
        nodeElement.innerHTML = `
            <div class="node-content">
                <div class="node-title">${node.title || 'Untitled'}</div>
                ${node.content ? `<div class="node-description">${node.content}</div>` : ''}
            </div>
            ${this.mindmap.options.editable ? `
                <div class="node-buttons">
                    <button class="add-btn">+</button>
                    <button class="edit-btn">✎</button>
                    <button class="delete-btn">×</button>
                </div>
            ` : ''}
        `;

        // 添加到容器
        this.nodeContainer.appendChild(nodeElement);
        this.nodeElements.set(node.id, nodeElement);

        // 递归渲染子节点
        if (node.children) {
            node.children.forEach(child => this.renderNode(child));
        }
    }

    // 渲染连接线
    renderConnections() {
        const renderConnection = (parent, child) => {
            const parentEl = this.nodeElements.get(parent.id);
            const childEl = this.nodeElements.get(child.id);

            if (!parentEl || !childEl) return;

            // 计算连接点
            const parentRect = parentEl.getBoundingClientRect();
            const childRect = childEl.getBoundingClientRect();
            const containerRect = this.containerElement.getBoundingClientRect();

            const parentX = parentRect.x + parentRect.width - containerRect.x;
            const parentY = parentRect.y + parentRect.height/2 - containerRect.y;
            const childX = childRect.x - containerRect.x;
            const childY = childRect.y + childRect.height/2 - containerRect.y;

            // 创建连接线路径
            const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');

            // 计算贝塞尔曲线控制点
            const controlX1 = parentX + 50;
            const controlX2 = childX - 50;

            path.setAttribute('d', `M ${parentX} ${parentY} C ${controlX1} ${parentY}, ${controlX2} ${childY}, ${childX} ${childY}`);
            path.setAttribute('stroke', '#888');
            path.setAttribute('stroke-width', '2');
            path.setAttribute('fill', 'none');

            this.svgElement.appendChild(path);
            this.connectionElements.set(`${parent.id}-${child.id}`, path);
        };

        // 递归处理所有连接
        const processNode = (node) => {
            if (node.children) {
                node.children.forEach(child => {
                    renderConnection(node, child);
                    processNode(child);
                });
            }
        };

        processNode(this.mindmap.root);
    }
}
```

