// 主存储管理器
class MasterStorage {
    constructor(options = {}) {
        this.options = {
            primaryAdapter: 'localStorage',
            backupAdapter: null,
            autoSave: true,
            ...options
        };

        this.adapters = new Map();
        this.quotaManager = new QuotaManager();
        this.initialized = false;
    }

    // 初始化
    async initialize() {
        if (this.initialized) return;

        // 注册默认适配器
        this.registerAdapter('localStorage', new LocalStorageAdapter());

        // 初始化配额管理器
        await this.quotaManager.initialize();

        this.initialized = true;
    }

    // 注册存储适配器
    registerAdapter(name, adapter) {
        this.adapters.set(name, adapter);
    }

    // 保存数据
    async save(key, data) {
        if (!this.initialized) await this.initialize();

        // 获取主适配器
        const primaryAdapter = this.adapters.get(this.options.primaryAdapter);
        if (!primaryAdapter) {
            return { success: false, error: 'Primary adapter not found' };
        }

        try {
            // 检查配额
            const dataSize = this.estimateDataSize(data);
            const quotaInfo = await this.quotaManager.checkQuota(dataSize);

            if (!quotaInfo.hasSpace) {
                // 尝试清理空间
                const cleanupResult = await this.quotaManager.cleanup();
                if (!cleanupResult.success) {
                    return { 
                        success: false, 
                        error: 'Storage quota exceeded',
                        details: cleanupResult 
                    };
                }
            }

            // 主存储保存
            const result = await primaryAdapter.save(key, data);

            // 备份存储保存
            if (result.success && this.options.backupAdapter) {
                const backupAdapter = this.adapters.get(this.options.backupAdapter);
                if (backupAdapter) {
                    backupAdapter.save(key, data).catch(err => {
                        console.warn('Backup save failed:', err);
                    });
                }
            }

            return result;
        } catch (error) {
            console.error('Storage save error:', error);
            return { success: false, error: error.message };
        }
    }

    // 加载数据
    async load(key) {
        if (!this.initialized) await this.initialize();

        // 尝试主适配器
        const primaryAdapter = this.adapters.get(this.options.primaryAdapter);
        if (primaryAdapter) {
            try {
                const result = await primaryAdapter.load(key);
                if (result.success) return result;
            } catch (error) {
                console.warn('Primary storage load failed:', error);
            }
        }

        // 尝试备份适配器
        if (this.options.backupAdapter) {
            const backupAdapter = this.adapters.get(this.options.backupAdapter);
            if (backupAdapter) {
                try {
                    return await backupAdapter.load(key);
                } catch (error) {
                    console.error('Backup storage load failed:', error);
                }
            }
        }

        return { success: false, error: 'Data not found' };
    }
}

// LocalStorage适配器
class LocalStorageAdapter {
    constructor() {
        this.prefix = 'mm:';
    }

    // 生成键
    getKey(key) {
        return `${this.prefix}${key}:data`;
    }

    // 保存数据
