/**
 * 数据验证器 - 检查和修复数据格式和一致性问题
 */
class DataValidator {
    constructor(dataManager) {
        this.dataManager = dataManager;
    }

    /**
     * 验证并修复脑图数据
     * @param {Object} mindmap - 脑图数据
     * @returns {Object} - 修复后的脑图数据
     */
    validateAndFixMindmap(mindmap) {
        if (!mindmap) return null;

        const result = {
            fixed: false,
            mindmap: {...mindmap},
            issues: []
        };

        // 检查格式
        if (!mindmap.format) {
            result.mindmap.format = 'node_tree';
            result.fixed = true;
            result.issues.push('缺少format字段');
        }

        // 检查数据节点
        if (!mindmap.data) {
            result.mindmap.data = { id: `root-${Date.now()}`, topic: '新脑图', children: [] };
            result.fixed = true;
            result.issues.push('缺少data对象');
        } else {
            // 修复根节点ID
            if (!mindmap.data.id) {
                result.mindmap.data.id = `root-${Date.now()}`;
                result.fixed = true;
                result.issues.push('根节点缺少ID');
            }

            // 修复根节点标题
            if (!mindmap.data.topic && !mindmap.data.label) {
                result.mindmap.data.topic = '未命名脑图';
