/**
 * DataManager - 统一的存储管理器
 * 作为系统的单一数据源，统一管理所有localStorage操作
 */
class DataManager {
    constructor() {
        this.prefix = 'mm:';
        this.listeners = new Map();
        this.cache = new Map();
        this.defaultTTL = 60 * 1000; // 缓存默认60秒

        // 统计信息
        this.stats = {
            reads: 0,
            writes: 0,
            errors: 0,
            cacheHits: 0,
            lastOperation: null
        };

        // 绑定到现有事件系统(如果存在)
        if (window.eventBus) {
            this._bindEvents();
        }
    }

    /**
     * 保存数据到存储
     * @param {string} key - 存储键
     * @param {*} data - 要存储的数据
     * @param {Object} options - 存储选项
     * @returns {Promise<boolean>} - 成功状态
     */
    async save(key, data, options = {}) {
        try {
            const fullKey = this._getFullKey(key);
            const serialized = JSON.stringify({
                data,
                meta: {
                    timestamp: Date.now(),
                    version: options.version || '1.0',
                    source: options.source || 'data_manager'
                }
            });

            // 尝试存储
            try {
                localStorage.setItem(fullKey, serialized);
            } catch (err) {
                // 处理存储配额错误
                if (err.name === 'QuotaExceededError') {
                    await this._handleStorageQuota();
                    // 重试保存
                    localStorage.setItem(fullKey, serialized);
                } else {
                    throw err;
                }
            }

            // 更新缓存
            this.cache.set(key, {
                data,
                expires: Date.now() + (options.cacheTTL || this.defaultTTL)
            });

            // 更新统计
            this.stats.writes++;
            this.stats.lastOperation = {
                type: 'write',
                key,
                timestamp: Date.now()
            };

            // 触发事件
            this._triggerListeners('save', { key, data });

            return true;
        } catch (error) {
            console.error(`[DataManager] 保存失败: ${key}`, error);
            this.stats.errors++;
            return false;
        }
    }

    /**
     * 从存储中加载数据
     * @param {string} key - 存储键
     * @param {Object} options - 加载选项
     * @returns {Promise<*>} - 加载的数据
     */
    async load(key, options = {}) {
        try {
            // 先检查缓存
            if (!options.skipCache) {
                const cached = this.cache.get(key);
                if (cached && cached.expires > Date.now()) {
                    this.stats.cacheHits++;
                    return cached.data;
                }
            }

            const fullKey = this._getFullKey(key);
            const serialized = localStorage.getItem(fullKey);

            if (!serialized) {
                return null;
            }

            // 尝试解析
            try {
                const parsed = JSON.parse(serialized);
                const result = parsed.data;

                // 更新缓存
                this.cache.set(key, {
                    data: result,
                    expires: Date.now() + (options.cacheTTL || this.defaultTTL)
                });

                // 更新统计
                this.stats.reads++;
                this.stats.lastOperation = {
                    type: 'read',
                    key,
                    timestamp: Date.now()
                };

                return result;
            } catch (parseError) {
                // 处理解析错误 - 尝试作为原始字符串处理
                console.warn(`[DataManager] 解析错误: ${key}, 尝试作为原始值返回`);
                return serialized;
            }
        } catch (error) {
            console.error(`[DataManager] 加载失败: ${key}`, error);
            this.stats.errors++;
            return null;
        }
    }

    /**
     * 从存储中移除数据
     * @param {string} key - 存储键
     * @returns {Promise<boolean>} - 成功状态
     */
    async remove(key) {
        try {
            const fullKey = this._getFullKey(key);
            localStorage.removeItem(fullKey);

            // 从缓存中移除
            this.cache.delete(key);

            // 触发事件
            this._triggerListeners('remove', { key });

            return true;
        } catch (error) {
            console.error(`[DataManager] 删除失败: ${key}`, error);
            this.stats.errors++;
            return false;
        }
    }

    /**
     * 检查键是否存在
     * @param {string} key - 存储键
     * @returns {Promise<boolean>} - 存在状态
     */
    async exists(key) {
        // 先检查缓存
        if (this.cache.has(key)) {
            const cached = this.cache.get(key);
            if (cached.expires > Date.now()) {
                return true;
            }
        }

        const fullKey = this._getFullKey(key);
        return localStorage.getItem(fullKey) !== null;
    }

    /**
     * 列出所有匹配模式的键
     * @param {string} pattern - 匹配模式 (可选)
     * @returns {Promise<Array<string>>} - 键列表
     */
    async listKeys(pattern = null) {
        try {
            const keys = [];
            const prefixLength = this.prefix.length;

            // 遍历所有localStorage键
            for (let i = 0; i < localStorage.length; i++) {
                const fullKey = localStorage.key(i);

                // 检查前缀
                if (fullKey.startsWith(this.prefix)) {
                    const key = fullKey.substring(prefixLength);

                    // 如果有模式，检查是否匹配
                    if (!pattern || this._matchPattern(key, pattern)) {
                        keys.push(key);
                    }
                }
            }

            return keys;
        } catch (error) {
            console.error(`[DataManager] 列举键失败`, error);
            return [];
        }
    }

    /**
     * 清理过期或不必要的数据
     * @returns {Promise<Object>} - 清理结果
     */
    async cleanup() {
        try {
            const result = {
                removed: 0,
                bytes: 0,
                keys: []
            };

            // 1. 清理缓存
            const now = Date.now();
            for (const [key, value] of this.cache.entries()) {
                if (value.expires <= now) {
                    this.cache.delete(key);
                }
            }

            // 2. 查找过期和临时数据
            const allKeys = await this.listKeys();
            const keysToRemove = [];

            for (const key of allKeys) {
                // 检查是否是临时数据
                if (key.includes('temp_') || key.includes('_tmp')) {
                    keysToRemove.push(key);
                    continue;
                }

                // 读取元数据检查过期时间
                try {
                    const fullKey = this._getFullKey(key);
                    const raw = localStorage.getItem(fullKey);
                    if (raw) {
                        const item = JSON.parse(raw);
                        const timestamp = item.meta?.timestamp || 0;

                        // 如果数据超过30天未更新，考虑移除
                        if (timestamp && (now - timestamp > 30 * 24 * 60 * 60 * 1000)) {
                            keysToRemove.push(key);
                        }
                    }
                } catch (e) {
                    // 解析错误，可能是格式不对
                    console.warn(`[DataManager] 清理时解析失败: ${key}`);
                }
            }

            // 3. 执行删除
            for (const key of keysToRemove) {
                const fullKey = this._getFullKey(key);
                const value = localStorage.getItem(fullKey);
                if (value) {
                    result.bytes += value.length * 2; // 粗略估计字节大小
                    result.keys.push(key);
                    await this.remove(key);
                    result.removed++;
                }
            }

            return result;
        } catch (error) {
            console.error(`[DataManager] 清理失败`, error);
            return { removed: 0, bytes: 0, keys: [] };
        }
    }

    /**
     * 获取存储使用统计
     * @returns {Promise<Object>} - 使用统计
     */
    async getUsageStats() {
        try {
            const allKeys = await this.listKeys();
            let totalSize = 0;
            let itemCount = allKeys.length;

            // 计算总大小
            for (const key of allKeys) {
                const fullKey = this._getFullKey(key);
                const value = localStorage.getItem(fullKey);
                if (value) {
                    totalSize += value.length * 2; // 粗略估计字节大小
                }
            }

            // 添加缓存统计
            const cacheCount = this.cache.size;

            return {
                itemCount,
                totalSize,
                totalSizeKB: Math.round(totalSize / 1024),
                cacheSize: cacheCount,
                operations: {
                    reads: this.stats.reads,
                    writes: this.stats.writes,
                    errors: this.stats.errors,
                    cacheHits: this.stats.cacheHits
                },
                lastOperation: this.stats.lastOperation
            };
        } catch (error) {
            console.error(`[DataManager] 获取使用统计失败`, error);
            return { error: error.message };
        }
    }

    /**
     * 添加存储事件监听器
     * @param {string} event - 事件名称 (save, load, remove)
     * @param {Function} callback - 回调函数
     * @returns {Function} - 取消监听的函数
     */
    addListener(event, callback) {
        if (!this.listeners.has(event)) {
            this.listeners.set(event, new Set());
        }
        this.listeners.get(event).add(callback);

        // 返回取消函数
        return () => {
            if (this.listeners.has(event)) {
                this.listeners.get(event).delete(callback);
            }
        };
    }

    /**
     * 转换为全局键名
     * @param {string} key - 原始键
     * @returns {string} - 带前缀的全局键
     */
    _getFullKey(key) {
        return `${this.prefix}${key}`;
    }

    /**
     * 检查键是否匹配模式
     * @param {string} key - 键名
     * @param {string} pattern - 匹配模式 (支持*通配符)
     * @returns {boolean} - 是否匹配
     */
    _matchPattern(key, pattern) {
        // 简单的通配符匹配
        const regexPattern = pattern
            .replace(/\./g, '\\.')
            .replace(/\*/g, '.*');
        const regex = new RegExp(`^${regexPattern}$`);
        return regex.test(key);
    }

    /**
     * 处理存储配额超出问题
     * @returns {Promise<void>}
     */
    async _handleStorageQuota() {
        console.warn('[DataManager] 存储配额超出，尝试清理');

        // 1. 首先清理缓存和临时数据
        const cleanupResult = await this.cleanup();
        console.log(`[DataManager] 清理结果: 移除了 ${cleanupResult.removed} 项，释放 ${cleanupResult.bytes} 字节`);

        // 2. 如果清理不够，考虑移除更多数据
        if (cleanupResult.removed === 0) {
            // TODO: 考虑实现更复杂的存储优先级策略
            console.warn('[DataManager] 清理不足，可能需要手动介入');
        }
    }

    /**
     * 触发监听器
     * @param {string} event - 事件名称
     * @param {*} data - 事件数据
     */
    _triggerListeners(event, data) {
        if (this.listeners.has(event)) {
            this.listeners.get(event).forEach(callback => {
                try {
                    callback(data);
                } catch (error) {
                    console.error(`[DataManager] 监听器错误: ${event}`, error);
                }
            });
        }

        // 通过全局事件总线触发
        if (window.eventBus) {
            window.eventBus.emit(`storage:${event}`, data);
        }
    }

    /**
     * 绑定到全局事件总线
     */
    _bindEvents() {
        if (window.eventBus) {
            window.eventBus.on('app:beforeunload', () => {
                // 在页面卸载前保存统计信息
                this._saveStats();
            });
        }
    }

    /**
     * 保存统计信息
     */
    _saveStats() {
        try {
            const statsKey = this._getFullKey('stats');
            localStorage.setItem(statsKey, JSON.stringify({
                timestamp: Date.now(),
                stats: this.stats
            }));
        } catch (error) {
            console.error('[DataManager] 保存统计信息失败', error);
        }
    }
}

