            migrated: 0,
            skipped: 0,
            details: []
        };

        try {
            // 检查旧式脑图数据
            const oldData = localStorage.getItem('mindmap_data_v1');
            if (!oldData) {
                return result;
            }

            // 解析旧数据
            try {
                const mindmapData = JSON.parse(oldData);

                // 检查格式
                if (mindmapData && mindmapData.format === 'node_tree') {
                    // 提取脑图ID
                    const mindId = mindmapData.data?.id || `legacy-${Date.now()}`;

                    // 创建新格式
                    const newFormat = {
                        format: 'node_tree',
                        data: mindmapData.data,
                        meta: {
                            mind_id: mindId,
                            format_version: 1,
                            saved_at: new Date().toISOString(),
                            source: 'migration',
                            migrated_from: 'mindmap_data_v1'
                        }
                    };

                    // 保存到新存储系统
                    await dataManager.save(`mind:${mindId}:data`, newFormat);
                    result.migrated++;
                    result.details.push({
                        id: mindId,
                        success: true,
                        source: 'mindmap_data_v1'
                    });
                } else {
                    result.skipped++;
                    result.details.push({
                        success: false,
                        reason: '无效的脑图格式',
                        source: 'mindmap_data_v1'
                    });
                }
            } catch (parseError) {
                result.skipped++;
                result.details.push({
