/**
 * 存储迁移助手 - 帮助迁移旧格式数据到新存储系统
 */
import dataManager from './DataManager.js';

class MigrationHelper {
    constructor() {
        this.legacyKeys = [
            'mindmap_data_v1',
            '__mind_full_cache_v1',
            'mm_project_catalog_v1'
        ];
    }

    /**
     * 检查并迁移旧格式数据
     * @returns {Promise<Object>} - 迁移结果
     */
    async migrateIfNeeded() {
        const result = {
            migrated: 0,
            skipped: 0,
            details: {}
        };

        // 检查和迁移脑图数据
        result.details.mindmap = await this._migrateMindmapData();
        result.migrated += result.details.mindmap.migrated;
        result.skipped += result.details.mindmap.skipped;

        // 检查和迁移项目目录
        result.details.catalog = await this._migrateProjectCatalog();
        result.migrated += result.details.catalog.migrated;
        result.skipped += result.details.catalog.skipped;

        return result;
    }

    /**
     * 迁移旧脑图数据
     * @returns {Promise<Object>} - 迁移结果
     */
    async _migrateMindmapData() {
        const result = {
            migrated: 0,
            skipped: 0,
            details: []
        };

        try {
            // 检查旧式脑图数据
            const oldData = localStorage.getItem('mindmap_data_v1');
            if (!oldData) {
                return result;
            }

            // 解析旧数据
            try {
                const mindmapData = JSON.parse(oldData);

                // 检查格式
                if (mindmapData && mindmapData.format === 'node_tree') {
                    // 提取脑图ID
                    const mindId = mindmapData.data?.id || `legacy-${Date.now()}`;

                    // 创建新格式
                    const newFormat = {
                        format: 'node_tree',
                        data: mindmapData.data,
                        meta: {
                            mind_id: mindId,
                            format_version: 1,
                            saved_at: new Date().toISOString(),
                            source: 'migration',
                            migrated_from: 'mindmap_data_v1'
                        }
                    };

                    // 保存到新存储系统
                    await dataManager.save(`mind:${mindId}:data`, newFormat);
                    result.migrated++;
                    result.details.push({
                        id: mindId,
                        success: true,
                        source: 'mindmap_data_v1'
                    });
                } else {
                    result.skipped++;
                    result.details.push({
                        success: false,
                        reason: '无效的脑图格式',
                        source: 'mindmap_data_v1'
                    });
                }
            } catch (parseError) {
                result.skipped++;
                result.details.push({
                    success: false,
                    reason: '解析错误',
                    error: parseError.message,
                    source: 'mindmap_data_v1'
                });
            }
        } catch (error) {
            console.error('[MigrationHelper] 迁移脑图数据失败', error);
        }

        return result;
    }

    /**
     * 迁移项目目录
     * @returns {Promise<Object>} - 迁移结果
     */
    async _migrateProjectCatalog() {
        const result = {
            migrated: 0,
            skipped: 0,
            details: []
        };

        try {
            // 检查旧式项目目录
            const oldCatalog = localStorage.getItem('mm_project_catalog_v1');
            if (!oldCatalog) {
                return result;
            }

            // 解析旧数据
            try {
                const projects = JSON.parse(oldCatalog);

                // 检查是否是数组
                if (Array.isArray(projects)) {
                    // 保存到新存储系统
                    await dataManager.save('registry:projects', projects);
                    result.migrated++;
                    result.details.push({
                        success: true,
                        count: projects.length,
                        source: 'mm_project_catalog_v1'
                    });
                } else {
                    result.skipped++;
                    result.details.push({
                        success: false,
                        reason: '项目目录不是数组',
                        source: 'mm_project_catalog_v1'
                    });
                }
            } catch (parseError) {
                result.skipped++;
                result.details.push({
                    success: false,
                    reason: '解析错误',
                    error: parseError.message,
                    source: 'mm_project_catalog_v1'
                });
            }
        } catch (error) {
            console.error('[MigrationHelper] 迁移项目目录失败', error);
        }

        return result;
    }

    /**
     * 验证迁移结果
     * @returns {Promise<Object>} - 验证结果
     */
    async validateMigration() {
        const result = {
            success: true,
            details: {}
        };

        try {
            // 1. 验证脑图数据
            const minds = await dataManager.listKeys('mind:*:data');
            result.details.minds = {
                count: minds.length,
                keys: minds
            };

            // 2. 验证项目目录
            const hasProjects = await dataManager.exists('registry:projects');
            if (hasProjects) {
                const projects = await dataManager.load('registry:projects');
                result.details.projects = {
                    count: Array.isArray(projects) ? projects.length : 0,
                    success: !!projects
                };
            } else {
                result.details.projects = {
                    count: 0,
                    success: false
                };
                result.success = false;
            }
        } catch (error) {
            console.error('[MigrationHelper] 验证迁移结果失败', error);
            result.success = false;
            result.error = error.message;
        }

        return result;
    }
}

