/**
 * 数据验证器 - 检查和修复数据格式和一致性问题
 */
class DataValidator {
    constructor(dataManager) {
        this.dataManager = dataManager;
    }

    /**
     * 验证并修复脑图数据
     * @param {Object} mindmap - 脑图数据
     * @returns {Object} - 修复后的脑图数据
     */
    validateAndFixMindmap(mindmap) {
        if (!mindmap) return null;

        const result = {
            fixed: false,
            mindmap: {...mindmap},
            issues: []
        };

        // 检查格式
        if (!mindmap.format) {
            result.mindmap.format = 'node_tree';
            result.fixed = true;
            result.issues.push('缺少format字段');
        }

        // 检查数据节点
        if (!mindmap.data) {
            result.mindmap.data = { id: `root-${Date.now()}`, topic: '新脑图', children: [] };
            result.fixed = true;
            result.issues.push('缺少data对象');
        } else {
            // 修复根节点ID
            if (!mindmap.data.id) {
                result.mindmap.data.id = `root-${Date.now()}`;
                result.fixed = true;
                result.issues.push('根节点缺少ID');
            }

            // 修复根节点标题
            if (!mindmap.data.topic && !mindmap.data.label) {
                result.mindmap.data.topic = '未命名脑图';
                result.fixed = true;
                result.issues.push('根节点缺少标题');
            } else if (mindmap.data.label && !mindmap.data.topic) {
                // 统一使用topic字段
                result.mindmap.data.topic = mindmap.data.label;
                result.fixed = true;
                result.issues.push('将label字段统一为topic');
            }

            // 确保children数组存在
            if (!Array.isArray(mindmap.data.children)) {
                result.mindmap.data.children = [];
                result.fixed = true;
                result.issues.push('缺少children数组');
            }

            // 递归修复子节点
            if (result.mindmap.data.children && result.mindmap.data.children.length > 0) {
                this._fixNodeContentRecursive(result.mindmap.data.children, result);
            }
        }

        // 检查元数据
        if (!mindmap.meta) {
            result.mindmap.meta = {
                mind_id: result.mindmap.data.id,
                format_version: 1,
                saved_at: new Date().toISOString(),
                source: 'validator'
            };
            result.fixed = true;
            result.issues.push('缺少meta元数据');
        } else {
            // 确保mind_id存在
            if (!mindmap.meta.mind_id) {
                result.mindmap.meta.mind_id = result.mindmap.data.id;
                result.fixed = true;
                result.issues.push('meta.mind_id缺失');
            }
        }

        return result;
    }

    /**
     * 递归修复节点内容
     * @param {Array} nodes - 节点数组
     * @param {Object} result - 结果对象
     */
    _fixNodeContentRecursive(nodes, result) {
        if (!Array.isArray(nodes)) return;

        for (let i = 0; i < nodes.length; i++) {
            const node = nodes[i];

            // 修复节点ID
            if (!node.id) {
                node.id = `node-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
                result.fixed = true;
                result.issues.push(`节点缺少ID，已生成新ID: ${node.id}`);
            }

            // 修复节点标题
            if (!node.topic && !node.label) {
                node.topic = '未命名节点';
                result.fixed = true;
                result.issues.push(`节点${node.id}缺少标题`);
            } else if (node.label && !node.topic) {
                node.topic = node.label;
                result.fixed = true;
                result.issues.push(`节点${node.id}将label字段统一为topic`);
            }

            // 修复节点内容一致性 - 关键修复
            this._fixNodeContent(node, result);

            // 确保children数组存在
            if (!Array.isArray(node.children)) {
                node.children = [];
                result.fixed = true;
                result.issues.push(`节点${node.id}缺少children数组`);
            }

            // 递归处理子节点
            if (node.children && node.children.length > 0) {
                this._fixNodeContentRecursive(node.children, result);
            }
        }
    }

    /**
     * 修复节点内容不一致问题
     * @param {Object} node - 节点对象
     * @param {Object} result - 结果对象
     */
    _fixNodeContent(node, result) {
        // 修复关键的内容不一致问题
        if (node.content && !node.data?.content) {
            // content存在但data.content不存在
            if (!node.data) node.data = {};
            node.data.content = node.content;
            result.fixed = true;
            result.issues.push(`节点${node.id}修复content同步到data.content`);
        } else if (!node.content && node.data?.content) {
            // data.content存在但content不存在
            node.content = node.data.content;
            result.fixed = true;
            result.issues.push(`节点${node.id}修复data.content同步到content`);
        } else if (node.content && node.data?.content && node.content !== node.data.content) {
            // 两者都存在但不一致，使用较长的版本
            if (node.content.length >= node.data.content.length) {
                node.data.content = node.content;
            } else {
                node.content = node.data.content;
            }
            result.fixed = true;
            result.issues.push(`节点${node.id}修复content和data.content不一致问题`);
        }
    }

    /**
     * 验证项目目录数据
     * @param {Array} projects - 项目数组
     * @returns {Object} - 验证结果
     */
    validateProjectCatalog(projects) {
        if (!Array.isArray(projects)) {
            return {
                valid: false,
                projects: [],
                issues: ['项目目录不是数组']
            };
        }

        const result = {
            valid: true,
            fixed: false,
            projects: [...projects],
            issues: [],
            duplicates: []
        };

        // 检查项目ID唯一性
        const idMap = new Map();
        const validProjects = [];

