### 简化版存储管理器

```javascript
/**
 * SimpleStorageManager - 简化的localStorage管理器
 * 专注于基本功能：存储、清理、错误处理
 */
class SimpleStorageManager {
    constructor() {
        this.prefix = 'mm:';
        this.maxKeys = 50; // 简单的键数量限制
        this.stats = {
            reads: 0,
            writes: 0,
            errors: 0,
            cleanups: 0
        };
    }

    /**
     * 存储数据
     */
    set(key, data) {
        try {
            // 检查是否需要清理
            if (this._getOurKeyCount() >= this.maxKeys) {
                this._cleanupOldest();
            }

            const fullKey = `${this.prefix}${key}`;
            const value = {
                data,
                timestamp: Date.now()
            };

            localStorage.setItem(fullKey, JSON.stringify(value));
            this.stats.writes++;

            console.log(`[SimpleStorage] 存储成功: ${key}`);
            return true;

        } catch (error) {
            console.error(`[SimpleStorage] 存储失败: ${key}`, error);
            this.stats.errors++;

            // 如果是配额错误，尝试清理后重试
            if (error.name === 'QuotaExceededError') {
                this._emergencyCleanup();
                try {
                    localStorage.setItem(`${this.prefix}${key}`, JSON.stringify({
                        data,
                        timestamp: Date.now()
                    }));
                    return true;
                } catch (retryError) {
                    console.error(`[SimpleStorage] 重试失败: ${key}`, retryError);
                }
            }

            return false;
        }
    }

    /**
     * 读取数据
     */
    get(key) {
        try {
            const fullKey = `${this.prefix}${key}`;
            const raw = localStorage.getItem(fullKey);

            if (!raw) {
                return null;
            }

            const parsed = JSON.parse(raw);
            this.stats.reads++;

            return parsed.data;

        } catch (error) {
            console.error(`[SimpleStorage] 读取失败: ${key}`, error);
            this.stats.errors++;
            return null;
        }
    }

    /**
     * 删除数据
     */
    remove(key) {
        try {
            const fullKey = `${this.prefix}${key}`;
            localStorage.removeItem(fullKey);
            return true;
        } catch (error) {
            console.error(`[SimpleStorage] 删除失败: ${key}`, error);
            this.stats.errors++;
            return false;
        }
    }

    /**
     * 获取我们的键数量
     */
    _getOurKeyCount() {
        let count = 0;
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && key.startsWith(this.prefix)) {
                count++;
            }
        }
        return count;
    }

    /**
     * 清理最旧的数据（简单LRU）
     */
    _cleanupOldest() {
        let oldestKey = null;
        let oldestTime = Infinity;

        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && key.startsWith(this.prefix)) {
                try {
                    const value = localStorage.getItem(key);
                    const parsed = JSON.parse(value);
                    const timestamp = parsed.timestamp || 0;

                    if (timestamp < oldestTime) {
                        oldestTime = timestamp;
                        oldestKey = key;
                    }
                } catch (e) {
                    // 解析失败的键直接删除
                    localStorage.removeItem(key);
                }
            }
        }

        if (oldestKey) {
            localStorage.removeItem(oldestKey);
            this.stats.cleanups++;
            console.log(`[SimpleStorage] 清理旧数据: ${oldestKey}`);
        }
    }

    /**
     * 紧急清理（保留关键数据）
     */
    _emergencyCleanup() {
        console.warn('[SimpleStorage] 执行紧急清理...');

        const keysToKeep = ['current:mindmap', 'settings']; // 关键数据
        let cleaned = 0;

        for (let i = localStorage.length - 1; i >= 0; i--) {
            const fullKey = localStorage.key(i);
            if (fullKey && fullKey.startsWith(this.prefix)) {
                const key = fullKey.substring(this.prefix.length);

                if (!keysToKeep.includes(key)) {
                    localStorage.removeItem(fullKey);
                    cleaned++;
                }
            }
        }

        console.warn(`[SimpleStorage] 紧急清理完成，清理了 ${cleaned} 项`);
        this.stats.cleanups++;
    }

    /**
     * 获取统计信息
     */
    getStats() {
        return {
            ...this.stats,
            keyCount: this._getOurKeyCount(),
            maxKeys: this.maxKeys
        };
    }
}

// 创建单例
const simpleStorage = new SimpleStorageManager();
export default simpleStorage;
```

### 简化版数据验证器

```javascript
/**
 * SimpleDataValidator - 简化的数据验证器
 * 只验证，不自动修复
 */
class SimpleDataValidator {
    /**
     * 验证脑图数据
     */
    validateMindmap(mindmapData) {
        const issues = [];

        if (!mindmapData) {
            issues.push('数据为空');
            return { valid: false, issues };
        }

        if (!mindmapData.format) {
            issues.push('缺少format字段');
        }

        if (!mindmapData.data) {
            issues.push('缺少data对象');
            return { valid: false, issues };
        }

        if (!mindmapData.data.id) {
            issues.push('根节点缺少ID');
        }

        if (!mindmapData.data.topic && !mindmapData.data.label) {
            issues.push('根节点缺少标题');
        }

        // 检查子节点结构
        if (mindmapData.data.children) {
            this._validateNodesRecursive(mindmapData.data.children, issues);
        }

        return {
            valid: issues.length === 0,
            issues,
            warnings: issues.length > 0 ? ['数据存在问题，建议检查源文件'] : []
        };
    }

    /**
     * 递归验证节点
     */
    _validateNodesRecursive(nodes, issues) {
        if (!Array.isArray(nodes)) {
            issues.push('children不是数组');
            return;
        }

        for (let i = 0; i < nodes.length; i++) {
            const node = nodes[i];

            if (!node.id) {
                issues.push(`第${i}个子节点缺少ID`);
            }

            if (!node.topic && !node.label) {
                issues.push(`节点${node.id || i}缺少标题`);
            }

            if (node.children) {
                this._validateNodesRecursive(node.children, issues);
            }
        }
    }
}

export default new SimpleDataValidator();
